/// The typed `inputSchema` of a built-in `CoreTools` handler, by tool name.
pub fn core_input_schema(name: &str) -> Option<Arc<JsonObject>> {
    static SCHEMAS: OnceLock<BTreeMap<String, Arc<JsonObject>>> = OnceLock::new();
    SCHEMAS
        .get_or_init(|| {
            core_tool_definitions()
                .into_iter()
                .map(|tool| (tool.name.to_string(), tool.input_schema))
                .collect()
        })
        .get(name)
        .cloned()
}

